SELECT p.id AS position_id, s.id AS signal_id, s.interval_code, s.candle_open_time, s.decision, s.original_decision, s.total_score, s.confidence_score, s.final_entry_allowed, s.primary_blocking_stage, s.latest_price, s.generated_at FROM paper_position p JOIN trade_signal s ON s.symbol = p.symbol AND s.generated_at BETWEEN p.opened_at - INTERVAL 70 MINUTE AND p.closed_at + INTERVAL 2 MINUTE WHERE p.id IN (182,172,162,158,143,137) AND (s.interval_code IN ('5m','1h') OR s.generated_at >= p.opened_at - INTERVAL 10 MINUTE) ORDER BY p.id, s.generated_at LIMIT 600